// Generated by scripts/build-work-overview.py.
(()=>{
    'use strict';
    const data=JSON.parse(document.getElementById('work-data').textContent);
    const $=id=>document.getElementById(id);
    const esc=value=>String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
    const scopes=new Map(data.scopes.map(s=>[s.id,s]));
    const resources=new Map(data.resources.map(r=>[r.id,r]));
    const resourceName=id=>resources.get(id)?.name||(id==='decision'?'제품 결정':'개발 환경');
    const tasks=new Map(data.tasks.map(t=>[t.id,t]));
    const state={tab:'overview',stage:'prepare',scope:'launch',resource:'all',kind:'all',query:'',stageFilter:null,pathFilter:null};
    const toneForScope={payment:'future',concurrency:'future',completed:'ready',launch:'wait',now:'ready',feature:'future',later:'future',conditional:'future',candidate:'decision'};
    const scopeBadge=id=>`<span class="badge ${toneForScope[id]}">${esc(scopes.get(id).label)}</span>`;
    function setTab(name){
      state.tab=name;
      for(const button of document.querySelectorAll('[role="tab"]')){
        const active=button.id==='tab-'+name;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;
      }
      for(const section of document.querySelectorAll('[role="tabpanel"]'))section.hidden=section.id!=='view-'+name;
    }
    function renderMap(){
      $('scope-map').innerHTML=data.scopes.map(s=>`<button type="button" class="scope-card" data-scope="${s.id}"><strong>${esc(s.label)} →</strong><p>${esc(s.flow)}</p><span>자원 · ${esc(s.resource)}</span></button>`).join('');
      $('parallel-work').innerHTML=data.parallel.map(p=>`<article class="parallel-card"><strong>병행 · ${esc(p.title)}</strong><p>${esc(p.flow)}</p><p class="due">마칠 시점 · ${esc(p.due)}</p><button class="text-button" type="button" data-task="${p.ids[0]}">결정·완료 기준 보기 →</button></article>`).join('');
      $('plan-overview').innerHTML=data.plans.map(p=>`<div class="plan-head"><h3>${esc(p.title)}</h3><span class="badge wait">${esc(p.state)}</span></div><p>${esc(p.summary)}</p><p class="flow-line">${esc(p.flow)}</p><p>${esc(p.branches)}</p><p class="plan-resources">필요한 자원 · ${esc(p.resources)}</p><div class="plan-links"><a href="${esc(p.source)}">현재 범위와 다음 행동 ↗</a><a href="${esc(p.detail)}">단계별 구현·검증 계획 ↗</a></div>`).join('');
      $('plan-work').innerHTML=data.plans.map(p=>`<strong>${esc(p.title)}</strong> <span class="badge wait">${esc(p.state)}</span><p>${esc(p.summary)}</p><div class="plan-links"><a href="${esc(p.detail)}">별도 계획의 작업 보기 ↗</a></div>`).join('');
      $('dependency-map').innerHTML=data.dependencies.map(d=>`<article class="dependency-card"><h3>${esc(d.title)}</h3><p>${esc(d.flow)}</p><p class="dependency-note">${esc(d.note)}</p>${d.ids.length?`<button type="button" class="text-button" data-dependency="${d.id}">관련 항목 보기 →</button>`:`<a href="${esc(d.href)}">기능별 계약·현재 상태 ↗</a>`}</article>`).join('');
    }
    function renderStage(){
      $('flow').innerHTML=data.stages.map(s=>`<button type="button" class="step" id="step-${s.id}" data-step="${s.id}" aria-pressed="${state.stage===s.id}"><span class="step-top"><span class="step-num">${s.number}</span><span class="step-state">${esc(s.state)}</span></span><strong>${esc(s.title)}</strong><span class="summary">${esc(s.summary)}</span></button>`).join('');
      const stage=data.stages.find(s=>s.id===state.stage);
      $('stage-detail').innerHTML=`<div><span class="detail-label">${stage.number} · 필요한 입력</span><p>${esc(stage.input)}</p><div class="stage-resources">${data.resources.filter(r=>r.stages.includes(stage.id)).map(r=>`<button type="button" data-show-resource="${r.id}">${esc(r.name)} ↗</button>`).join('')}</div><button class="text-button" type="button" data-scope="launch" data-stage="${stage.id}">이 단계의 항목 ${stage.ids.length}개 보기 →</button></div><div><span class="detail-label">할 행동</span><p>${esc(stage.action)}</p></div><div><span class="detail-label">다음 단계로 가는 기준</span><p>${esc(stage.exit)}</p></div>`;
    }
    function renderResources(){
      const first=['server','storage','apple','brand','devices','access'];
      $('resource-summary').innerHTML=first.map(id=>{const r=resources.get(id);return `<div class="resource-mini"><button type="button" data-show-resource="${id}" class="resource-name">${esc(r.name)} ↗</button><span class="badge ${r.tone}">${esc(r.state)}</span></div>`;}).join('');
      $('resource-grid').innerHTML=data.resources.map(r=>`<article class="resource-card" id="resource-${r.id}" tabindex="-1"><div class="resource-title"><h3>${esc(r.name)}</h3><span class="badge ${r.tone}">${esc(r.state)}</span></div><p>${esc(r.current)}</p><div><span class="detail-label">준비할 입력</span><p class="need">${esc(r.need)}</p></div><div><span class="detail-label">준비되면 열리는 것</span><p class="unlock">${esc(r.unlock)}</p></div><span class="owner">${esc(r.owner)}</span><div class="card-actions"><button type="button" class="text-button" data-resource="${r.id}">관련 항목 보기 →</button><a href="${esc(r.href)}">${esc(r.link)} ↗</a>${r.extraHref?`<a href="${esc(r.extraHref)}">${esc(r.extraLink)} ↗</a>`:''}</div></article>`).join('');
      $('resource-filter').insertAdjacentHTML('beforeend',data.resources.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join(''));
    }
    function renderWork(){
      const choices=[{id:'all',label:'전체'},...data.scopes];
      $('scope-choices').innerHTML=choices.map(s=>`<button class="chip" id="scope-${s.id}" type="button" data-filter-scope="${s.id}" aria-pressed="${state.scope===s.id}">${esc(s.label)}<b>${s.id==='all'?data.tasks.length:data.tasks.filter(t=>t.scope===s.id).length}</b></button>`).join('');
      const normalize=value=>value.toLocaleLowerCase('ko-KR').replace(/캘린더/g,'calendar');
      const query=normalize(state.query);
      const filtered=data.tasks.filter(t=>(state.scope==='all'||t.scope===state.scope)&&(state.resource==='all'||t.resources.includes(state.resource))&&(state.kind==='all'||t.kind===state.kind)&&(!state.stageFilter||t.stage===state.stageFilter)&&(!state.pathFilter||data.dependencies.find(d=>d.id===state.pathFilter).ids.includes(t.id))&&(!query||normalize([t.id,t.title,t.description,t.condition,t.resources.map(resourceName).join(' ')].join(' ')).includes(query)));
      const label=state.scope==='all'?'전체 범위':scopes.get(state.scope).label;
      const planMatch=state.scope==='all'&&state.kind==='all'&&!state.stageFilter&&!state.pathFilter&&data.plans.some(p=>(state.resource==='all'||p.resourceIds.includes(state.resource))&&(!query||normalize([p.title,p.summary,p.flow,p.resources].join(' ')).includes(query)));
      $('plan-work').hidden=!planMatch;
      $('result-count').textContent=`${label} · ${filtered.length}개 항목`+(state.scope!=='all'?' · '+scopes.get(state.scope).note:'')+(planMatch?' · 별도 공유 개선 계획 있음':'');
      const focusLabel=state.stageFilter?data.stages.find(s=>s.id===state.stageFilter).title:state.pathFilter?data.dependencies.find(d=>d.id===state.pathFilter).title:null;
      $('stage-filter').innerHTML=focusLabel?`<span class="selected-filter">${esc(focusLabel)}<button type="button" id="clear-stage-filter" aria-label="흐름 필터 해제">×</button></span>`:'';
      $('work-list').innerHTML=filtered.length?filtered.map(t=>`<button type="button" class="work-row" data-task="${t.id}"><span class="work-meta">${scopeBadge(t.scope)}<span class="task-id">${esc(t.id)} · ${esc(t.kind)}</span></span><span class="work-body"><span class="task-title">${esc(t.title)}</span><span class="task-condition">${esc(t.condition)}</span></span><span class="work-resources">${t.resources.map(resourceName).map(esc).join(' · ')}</span><span class="row-arrow" aria-hidden="true">↗</span></button>`).join(''):(planMatch?'<div class="empty">관련 작업은 위 공유 개선 계획에서 확인합니다.</div>':'<div class="empty">이 조건에 맞는 항목이 없습니다.<br>검색어나 필터를 줄여 보세요.</div>');
    }
    function showWork(scope,resource='all',stage=null,path=null){
      state.scope=scope;state.resource=resource;state.stageFilter=stage;state.pathFilter=path;state.kind='all';state.query='';$('query').value='';$('resource-filter').value=resource;$('kind-filter').value='all';renderWork();setTab('work');$('tab-work').focus();
    }
    function showTask(id){
      const t=tasks.get(id);if(!t)return;
      const conditionLabel=t.section.startsWith('9.')?'끝났다고 볼 기준':'진행 상태·다음 조건';
      const resourceLabels=t.resources.map(resourceName).join(' · ');
      const notes=(t.sourceNotes||[]).map(note=>`<p>${esc(note)}</p>`).join('');
      const evidence=t.evidenceLinks.map(link=>`<a href="${esc(link.href)}">${esc(link.label)} ↗</a>`).join('');
      const owners=[...new Set(t.resources.map(id=>resources.get(id)?.owner||(id==='decision'?'사용자 결정':'개발')))];
      $('dialog-content').innerHTML=`<div class="dialog-head"><div><div>${scopeBadge(t.scope)} <span class="tiny">${esc(t.id)} · ${esc(t.kind)}</span></div><h2 id="dialog-title">${esc(t.title)}</h2></div><button type="button" class="close" id="close-dialog" aria-label="상세 닫기">×</button></div><p class="dialog-description">${esc(t.description)}</p><div class="dialog-facts"><div><span class="detail-label">${conditionLabel}</span><p class="condition">${esc(t.condition)}</p></div><div><span class="detail-label">필요한 자원</span><p class="condition">${esc(resourceLabels)}</p><p class="tiny" style="margin-top:8px">준비·결정: ${owners.map(esc).join(' · ')}</p></div></div>${t.kind==='조사·확인'?'<p class="tiny">조사 결과로 재현·반증한 뒤 수정 범위를 정합니다. 아직 확정 결함으로 세지 않습니다.</p>':''}${evidence?`<details class="dialog-evidence"><summary>판단 근거 문서 보기</summary>${evidence}</details>`:''}${notes?`<details class="dialog-evidence"><summary>작업공간 원문 위치</summary>${notes}</details>`:''}<div class="dialog-links"><a href="${esc(t.source)}">이 항목 바로가기 ↗</a><a href="qa/feature-status.html">기능별 구현·검사 기록 ↗</a></div><p class="dialog-label">자세한 조건과 완료 기준은 위 원문을 따릅니다.</p>`;
      $('task-dialog').showModal();$('close-dialog').focus();
    }
    document.addEventListener('click',event=>{
      const target=event.target.closest('button');if(!target)return;
      if(target.dataset.task){showTask(target.dataset.task);return;}
      if(target.dataset.step){state.stage=target.dataset.step;renderStage();$('step-'+state.stage).focus();return;}
      if(target.hasAttribute('data-show-resources')){setTab('resources');return;}
      if(target.dataset.showResource){setTab('resources');const card=$('resource-'+target.dataset.showResource);card.focus();card.scrollIntoView?.({block:'center'});return;}
      if(target.dataset.dependency){showWork('all','all',null,target.dataset.dependency);return;}
      if(target.dataset.resource){showWork('all',target.dataset.resource);return;}
      if(target.dataset.scope){showWork(target.dataset.scope,'all',target.dataset.stage||null);return;}
      if(target.dataset.filterScope){state.scope=target.dataset.filterScope;state.stageFilter=null;state.pathFilter=null;renderWork();$('scope-'+state.scope).focus();return;}
      if(target.getAttribute('role')==='tab'){setTab(target.id.slice(4));return;}
      if(target.id==='close-dialog'){$('task-dialog').close();return;}
      if(target.id==='clear-stage-filter'){state.stageFilter=null;state.pathFilter=null;renderWork();$('tab-work').focus();return;}
      if(target.id==='reset-filters'){showWork('all');return;}
      if(target.id==='print-page')window.print();
    });
    document.querySelector('[role="tablist"]').addEventListener('keydown',event=>{
      if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
      event.preventDefault();const all=[...document.querySelectorAll('[role="tab"]')];const current=all.indexOf(document.activeElement);const index=event.key==='Home'?0:event.key==='End'?all.length-1:(current+(event.key==='ArrowRight'?1:-1)+all.length)%all.length;setTab(all[index].id.slice(4));all[index].focus();
    });
    $('query').addEventListener('input',event=>{state.query=event.target.value;renderWork();});
    $('resource-filter').addEventListener('change',event=>{state.resource=event.target.value;state.stageFilter=null;state.pathFilter=null;renderWork();});
    $('kind-filter').addEventListener('change',event=>{state.kind=event.target.value;renderWork();});
    $('task-dialog').addEventListener('click',event=>{if(event.target===$('task-dialog'))$('task-dialog').close();});
    renderMap();renderStage();renderResources();
    $('kind-filter').insertAdjacentHTML('beforeend',[...new Set(data.tasks.map(t=>t.kind))].map(kind=>`<option value="${esc(kind)}">${esc(kind)}</option>`).join(''));
    $('versions').innerHTML=data.versions.map(v=>`<span>${esc(v.name)} <code>${esc(v.commit)}</code></span>`).join('');
    renderWork();

    function readRoute(){
      const hash=decodeURIComponent(window.location.hash.slice(1));
      if(hash.startsWith('task-')){setTab('work');if(tasks.has(hash.slice(5)))showTask(hash.slice(5));return;}
      if($('task-dialog').open)$('task-dialog').close();
      const views={'view-overview':'overview','view-resources':'resources','view-work':'work'};
      setTab(views[hash]||'overview');
      if(hash==='view-work')showWork('all');
    }
    window.addEventListener('hashchange',readRoute);
    readRoute();
  })();
